class Solution {
  public String reverseByType(String s) {
    char[] c = s.toCharArray();
    reverseWhere(c, true);
    reverseWhere(c, false);
    return new String(c);
  }

  // reverses, in place, the characters that are letters (or non-letters)
  private void reverseWhere(char[] c, boolean letters) {
    int i = 0, j = c.length - 1;
    while (i < j) {
      if (Character.isLetter(c[i]) != letters) i++;
      else if (Character.isLetter(c[j]) != letters) j--;
      else {
        char t = c[i];
        c[i++] = c[j];
        c[j--] = t;
      }
    }
  }
}
